const visual = {
  prepare: function (input) {
    var texts = [
      '2', 'x²', '−7', 'x', '+', '3', '=', '0',
      'a = 2', 'b = −7', 'c = 3',
      'x =',
      '−', 'b', '±', '√(', 'b', '² − 4', 'a', 'c', ')',
      '2', 'a',
      'Δ = b² − 4ac', '= (−7)² − 4·2·3', '= 49 − 24',
      'Δ = 25'
    ];
    var out = [];
    var i;
    for (i = 0; i < texts.length; i = i + 1) {
      out.push({ kind: 'text', payload: texts[i] });
    }
    return out;
  },

  render: function (input, metrics) {
    var DW = 640;
    var DH = 400;
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / DW, H / DH);
    if (!isFinite(s) || s <= 0) { s = 1; }
    var ox = (W - DW * s) / 2;
    var oy = (H - DH * s) / 2;

    function X(v) { return ox + v * s; }
    function Y(v) { return oy + v * s; }
    function SW(v) { var w = v * s; return w < 0.6 ? 0.6 : w; }

    function seg(x1, y1, x2, y2) {
      return [['M', X(x1), Y(y1)], ['L', X(x2), Y(y2)]];
    }

    function roundRect(x, y, w, h, r) {
      return [
        ['M', X(x + r), Y(y)],
        ['L', X(x + w - r), Y(y)],
        ['Q', X(x + w), Y(y), X(x + w), Y(y + r)],
        ['L', X(x + w), Y(y + h - r)],
        ['Q', X(x + w), Y(y + h), X(x + w - r), Y(y + h)],
        ['L', X(x + r), Y(y + h)],
        ['Q', X(x), Y(y + h), X(x), Y(y + h - r)],
        ['L', X(x), Y(y + r)],
        ['Q', X(x), Y(y), X(x + r), Y(y)],
        ['Z']
      ];
    }

    function lbl(i, dx, dy, h, v, color) {
      return {
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: X(dx), y: Y(dy) },
        hAlign: h,
        vAlign: v,
        color: color
      };
    }

    var DARK = '#1F2937';
    var BLUE = '#1D4ED8';
    var RED = '#DC2626';
    var GREEN = '#047857';
    var RULE = '#CBD5E1';
    var CHIP = '#FDE68A';
    var CHIP_TEXT = '#92400E';

    var kids = [];

    kids.push({ type: 'path', pathId: 'chip', fill: CHIP });
    kids.push({ type: 'path', pathId: 'rule-top', fill: RULE, stroke: { width: SW(1) } });
    kids.push({ type: 'path', pathId: 'rule-mid', fill: RULE, stroke: { width: SW(1) } });
    kids.push({ type: 'path', pathId: 'lead-a', fill: BLUE, stroke: { width: SW(2), cap: 'round' } });
    kids.push({ type: 'path', pathId: 'lead-b', fill: RED, stroke: { width: SW(2), cap: 'round' } });
    kids.push({ type: 'path', pathId: 'lead-c', fill: GREEN, stroke: { width: SW(2), cap: 'round' } });
    kids.push({ type: 'path', pathId: 'frac-bar', fill: DARK, stroke: { width: SW(2.2) } });

    kids.push(lbl(0, 132, 50, 'center', 'middle', BLUE));
    kids.push(lbl(1, 160, 50, 'center', 'middle', DARK));
    kids.push(lbl(2, 206, 50, 'center', 'middle', RED));
    kids.push(lbl(3, 232, 50, 'center', 'middle', DARK));
    kids.push(lbl(4, 270, 50, 'center', 'middle', DARK));
    kids.push(lbl(5, 298, 50, 'center', 'middle', GREEN));
    kids.push(lbl(6, 340, 50, 'center', 'middle', DARK));
    kids.push(lbl(7, 368, 50, 'center', 'middle', DARK));

    kids.push(lbl(8, 132, 84, 'center', 'top', BLUE));
    kids.push(lbl(9, 206, 84, 'center', 'top', RED));
    kids.push(lbl(10, 298, 84, 'center', 'top', GREEN));

    kids.push(lbl(11, 190, 190, 'right', 'middle', DARK));
    kids.push(lbl(12, 206, 180, 'center', 'bottom', DARK));
    kids.push(lbl(13, 218, 180, 'center', 'bottom', RED));
    kids.push(lbl(14, 232, 180, 'center', 'bottom', DARK));
    kids.push(lbl(15, 250, 180, 'center', 'bottom', DARK));
    kids.push(lbl(16, 268, 180, 'center', 'bottom', RED));
    kids.push(lbl(17, 287, 180, 'center', 'bottom', DARK));
    kids.push(lbl(18, 308, 180, 'center', 'bottom', BLUE));
    kids.push(lbl(19, 319, 180, 'center', 'bottom', GREEN));
    kids.push(lbl(20, 329, 180, 'center', 'bottom', DARK));
    kids.push(lbl(21, 260, 198, 'center', 'top', DARK));
    kids.push(lbl(22, 272, 198, 'center', 'top', BLUE));

    kids.push(lbl(23, 150, 274, 'left', 'middle', DARK));
    kids.push(lbl(24, 168, 306, 'left', 'middle', DARK));
    kids.push(lbl(25, 168, 338, 'left', 'middle', DARK));
    kids.push(lbl(26, 473, 296, 'center', 'middle', CHIP_TEXT));

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'chip', commands: roundRect(400, 266, 146, 60, 14) },
        { id: 'rule-top', commands: seg(60, 118, 580, 118) },
        { id: 'rule-mid', commands: seg(60, 244, 580, 244) },
        { id: 'lead-a', commands: seg(132, 62, 132, 80) },
        { id: 'lead-b', commands: seg(206, 62, 206, 80) },
        { id: 'lead-c', commands: seg(298, 62, 298, 80) },
        { id: 'frac-bar', commands: seg(196, 190, 338, 190) }
      ],
      root: { type: 'group', children: kids }
    };
  }
};
